# ---- named tunables ----
# OPEN_HEALTH: engage with an opener only at or above this fraction of max health
# OPEN_LOCAL: local_strength(6) must exceed this (a fight we are not outnumbered in)
# RETREAT_HEALTH: retreat toward spawn and recall below this fraction of max health

# one fight step: ranged champions step off an adjacent enemy, cast by ability type, basic attack,
# attack reset cast on self after the attack, then a second attack
def fight(u):
    if i_am_ranged() and distance(position(), unit_position(u)) <= 1:
        move_away_from( unit_position(u) )
    if ability_ready(0) and not slot_is_dash(0) and not slot_is_reset(0):
        if slot_is_shield(0) or slot_is_heal(0):
            cast_self(0)
        elif distance(position(), unit_position(u)) <= slot_range(0):
            cast_at_unit(0, u)
    if ability_ready(1) and not slot_is_dash(1) and not slot_is_reset(1):
        if slot_is_shield(1) or slot_is_heal(1):
            cast_self(1)
        elif distance(position(), unit_position(u)) <= slot_range(1):
            cast_at_unit(1, u)
    if can_attack():
        attack(u)
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
        if ability_ready(1) and slot_is_reset(1):
            cast_self(1)
        if can_attack():
            attack(u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

