let tt_reach = exists(tt) and (distance(position(), unit_position(tt)) <= 1 or (i_am_ranged() and distance(position(), unit_position(tt)) <= 3))
if tt_reach and not contains( spawn_region(enemy()), unit_position(tt) ):
    fight(tt)
    end_turn()

# otherwise name the weakest enemy in reach as the team target and fight it
# (an enemy on its own spawn is healed every turn: skip it, 00reverse-spiral)
let foe = weakest( filter( enemies_visible(), in_attack_range() ) )
if exists(foe) and not contains( spawn_region(enemy()), unit_position(foe) ):
    set_team_target(foe)
    fight(foe)
    end_turn()

