let lead = nearest( enemies_visible() )
if exists(lead) and health() >= 0.75 * max_health() and not contains( spawn_region(enemy()), unit_position(lead) ):
    let lead_d = distance(position(), unit_position(lead))
    if ability_ready(0) and slot_stun(0) > 0 and lead_d <= slot_range(0) + slot_radius(0) and (not slot_is_dash(0) or fuel_remaining() > 30000):
