# v2 (combat micro on v1, plus banking):
#  - kept from v1: fight() with team-target focus fire and ability/reset sequencing, outnumbered
#    disengage (fuel-gated dash), join-the-focus step-in, melee dash opener, ranged stun opener,
#    retreat/recall rules, shard buying, altar-safe tributing, camp farming, monolith fallback.
#  - new: bank mid-size bags (12+ gems) when no enemy champion is visible within 8 tiles, so
#    carriers turn gems into score sooner without walking into fights while carrying them.

def fight(u):
    set_team_target(u)
    if ability_ready(0):
        if slot_is_shield(0) or slot_is_heal(0):
            cast_self(0)
        elif slot_is_damage(0) or slot_is_aoe(0) or slot_is_stun(0):
            cast_at_unit(0, u)
    if ability_ready(1):
        if slot_is_shield(1) or slot_is_heal(1):
            cast_self(1)
        elif slot_is_damage(1) or slot_is_aoe(1) or slot_is_stun(1):
            cast_at_unit(1, u)
    attack(u)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(u)
    end_turn()

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

