# v3: v1 + combat micro.
# (1) Reset abilities are never cast at the enemy; they are only self-cast after a basic attack.
#     Casting a reset at the enemy fails, and the measured fix gained about +9.7 points.
# (2) Casts are ordered stun first, then damage, then shield/heal. Only one cast succeeds per turn,
#     so the stun lands before the burst.
# (3) Stun opener: when healthy and an enemy is just outside basic reach but inside the stun's range,
#     open with the stun (or a stunning dash), name it the team target, then close and hit.
# (4) Retreat dashes are fuel-gated.
# Farming, tributing and recall rules are unchanged from v1.

# offensive cast by type: stun or damage at the unit; never a reset, dash, shield or heal
def cast_hit(slot, u):
    if ability_ready(slot):
        if not slot_is_dash(slot) and not slot_is_reset(slot) and not slot_is_shield(slot) and not slot_is_heal(slot):
            cast_at_unit(slot, u)

# defensive cast on self: shield or heal
def cast_def(slot):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# stun opener at range: a stunning dash or a stun cast
def open_with(slot, u):
    if ability_ready(slot) and slot_stun(slot) > 0:
        if distance(position(), unit_position(u)) <= slot_range(slot) + slot_radius(slot):
            if slot_is_dash(slot):
                if fuel_remaining() > 40000:
                    dash_towards(slot, unit_position(u))
            elif not slot_is_reset(slot):
                cast_at_unit(slot, u)

# full fight step on a unit in reach: stun first, then damage, then shield/heal, basic, reset, basic
def fight(u):
    if ability_ready(0) and slot_stun(0) > 0 and not slot_is_dash(0):
        cast_at_unit(0, u)
    if ability_ready(1) and slot_stun(1) > 0 and not slot_is_dash(1):
        cast_at_unit(1, u)
    if ability_ready(0):
        if not slot_is_dash(0) and not slot_is_reset(0) and not slot_is_shield(0) and not slot_is_heal(0):
            cast_at_unit(0, u)
    if ability_ready(1):
        if not slot_is_dash(1) and not slot_is_reset(1) and not slot_is_shield(1) and not slot_is_heal(1):
            cast_at_unit(1, u)
    if ability_ready(0):
        if slot_is_shield(0) or slot_is_heal(0):
            cast_self(0)
    if ability_ready(1):
        if slot_is_shield(1) or slot_is_heal(1):
            cast_self(1)
    attack(u)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(u)

